# Дополнительные факты, чтобы каждое видео было 30+ секунд. Вставляются перед финальной сценой.
def t(x): return {"type": "text", "text": x}
def c(v, unit, cap=None, dec=0):
    d = {"type": "count", "value": v, "unit": unit, "decimals": dec}
    if cap: d["caption"] = cap
    return d
def cmp(title, items, cap=None):
    d = {"type": "compare", "title": title, "items": items}
    if cap: d["caption"] = cap
    return d

